export const example=()=>({id:crypto.randomUUID(),title:'The space between',client:'Northlight Films',description:'A title sequence that sets the tone before the story begins.',deliverables:'One 30-second opening title sequence\nCreative direction, design & animation\n4K master + 1080p delivery',currency:'NZD',tax:'Excludes any applicable tax',rate:1200,days:12,costs:600,fee:15000,deposit:50,start:'2026-11-02',conceptDays:5,animationDays:8,reviewDays:2,reviews:2,finishDays:2,inputs:'Logo files in vector format\nFinal title and credit list\nPicture reference and technical delivery specs',terms:'The fee covers the deliverables and review rounds listed on this page.\nAdditional work or a change of direction will be quoted and agreed before proceeding.\nPlease send one consolidated set of feedback per review round.\nThe schedule depends on receiving materials, feedback and payments on time. If something moves, we will agree revised dates together.',paymentNote:'Deposit to book the project. Balance before release of final masters.',rights:'Usage rights, source files and any third-party licences to be agreed before work begins.'});
export function addDays(date,n){const d=new Date(date+'T12:00:00Z');let count=0;while(count<n){d.setUTCDate(d.getUTCDate()+1);if(d.getUTCDay()!==0&&d.getUTCDay()!==6)count++}return d.toISOString().slice(0,10)}
export function stages(p){let cursor=p.start;const list=[{name:'Kick-off',start:cursor,end:cursor,owner:'Together',color:'#bdd39d',body:`${p.client} supplies:\n${p.inputs}\n\nRoll confirms the brief and receives the ${p.deposit}% deposit.`}];function add(name,days,owner,color,body){const start=cursor;cursor=addDays(cursor,days);list.push({name,start,end:cursor,owner,color,body})}add('Direction',p.conceptDays,'Roll','#c6d8ac','Creative exploration, design and a proposed visual direction.');for(let i=0;i<p.reviews;i++){add(`Review ${i+1}`,p.reviewDays,p.client,'#c6cced',`Send one consolidated set of feedback within ${p.reviewDays} working day${p.reviewDays===1?'':'s'}.\n${i===0?'Approve the creative direction before animation begins.':'Review the animation and flag adjustments within the agreed scope.'}`);if(i===0)add('Animation',p.animationDays,'Roll','#b8cec5','Bring the approved direction to life through motion, timing and finishing.');else if(i<p.reviews-1)add('Refinements',p.finishDays,'Roll','#b8cec5','Apply the consolidated feedback before the next review.')}add('Final delivery',p.finishDays,'Roll','#e2c39d','Apply final agreed refinements and deliver the listed masters once the balance is paid.');return list}
export function clientProject(p){const {rate,days,costs,...safe}=p;return safe}
export function validate(p){return p&&typeof p.title==='string'&&p.title.length<=200&&typeof p.client==='string'&&['description','deliverables','inputs','terms','paymentNote','rights','tax'].every(k=>typeof p[k]==='string'&&p[k].length<=10000)&&['NZD','USD','AUD','GBP','EUR'].includes(p.currency)&&Number.isFinite(p.fee)&&p.fee>=0&&p.fee<=1e9&&Number.isFinite(p.deposit)&&p.deposit>=0&&p.deposit<=100&&/^\d{4}-\d{2}-\d{2}$/.test(p.start)&&!Number.isNaN(Date.parse(p.start))&&['conceptDays','animationDays','reviewDays','finishDays','reviews'].every(k=>Number.isInteger(p[k])&&p[k]>=1&&p[k]<=90)&&p.reviews<=6}
export function encode(p){const bytes=new TextEncoder().encode(JSON.stringify(clientProject(p)));return btoa(Array.from(bytes,b=>String.fromCharCode(b)).join('')).replaceAll('+','-').replaceAll('/','_').replaceAll('=','')}
export function decode(s){if(s.length>100000)throw Error('Too large');const p=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(Uint8Array.from(atob(s.replaceAll('-','+').replaceAll('_','/')),c=>c.charCodeAt(0))));if(!validate(p))throw Error('Invalid project');return p}
